/// 界面文案表（zh-Hans），编号与 docs/UI-COPY.md 一一对应。
extension CopyTables {
    static let zhHansJSON = #"""
{"A01": "👇 请在下面完成校园网登录吧。放心，咱们程序绝对不会偷偷保存或上传你的明文密码哦 🔒💖！", "A02": "🚀 已经呼叫你的默认浏览器打开登录页啦！", "A03": "🛡️ 没帮你自动打开：因为发现这个网址不在咱们吉大的 jlu.edu.cn 域名下哦 🧐", "A04": "🌐 在浏览器里输完密码成功登录后，记得回到这里点一下「已完成登录」哦 🙋‍♂️！整个过程咱们程序连碰都不会碰你的明文密码，安全感拉满 🛡️✨！", "A05": "⚠️ 请先再三确认你现在连的 Wi-Fi 真的是学校官方的 JLU.WIFI 或 JLU.PC，而且这个网址看着靠谱可信，咱们再继续往下走哦 🕵️‍♂️✨！", "A06": "🔄 重新打开登录页", "A07": "🦸‍♂️ 我确认过了，仍要打开这个页面", "A08": "✖️ 算了，取消", "A09": "🎉 我已完成登录啦！", "A10": "🚨 警惕！这个登录页面的网址居然不是 jlu.edu.cn 结尾的哦 🧐", "A11": "⚠️ 只有当你百分百确认当前连的 Wi-Fi 是学校正牌的 JLU.WIFI / JLU.PC 时，才点继续哦；", "A12": "🙅‍♂️ 如果连上了名字奇奇怪怪的可疑野鸡网络，千万别在里面输入你的宝贵账号和密码呀 🛡️！", "A13": "😭 哎呀，校园网认证还没跑通呢", "A14": "🔄 重新测一次", "A15": "💡 如果你现在确实在校外（比如用手机热点或家里宽带 🏠），想看校内系统得走 WebVPN 通道哦 🌉；要是你明明插着网线坐在寝室里，那就先点重试认证看看 🔄。点下面的按钮会直接帮你打开 WebVPN 并贴心复制好账号哒 📋✨！", "A16": "🌉 打开吉大 WebVPN", "A17": "🔑 复制密码", "A18": "🐾 超简单三步走：网页打开后在「师生普通登录」里选统一身份认证 👉 直接粘贴账号（已经帮你复制好啦 📋）👉 输入密码登录 👉 搞定后回来点一下「重测」就 OK 啦 🎉！", "A19": "✅ 账号已经帮你复制好啦：{…} ✨", "A20": "🙈 你还没有保存过账号呢——先去「设置」里填一次吧 ✍️！", "A21": "🤔 电脑里还没有存过密码哦——先去「设置」里保存一次吧 💾！", "A22": "🔐 密码已复制！为了保护隐私，60 秒后会自动清空剪贴板哦 ⏱️🛡️", "A23": "🏫 校园网欢迎门户", "A24": "🌐 学校的门户页（就是每次连上网常弹出来的欢迎/通知广告页）会直接用你的系统浏览器打开哦 ✨。", "A25": "🛡️ 咱们不在小巧的 App 里面硬塞网页加载器，这样能彻底避免网页渲染崩溃，让软件永远轻快稳定 🍃✨！", "A26": "🚀 在浏览器中打开看看", "A27": "📭 暂时还没收集到门户地址呢", "A28": "💡 先成功连接一次校园网（或者让程序被学校的未认证门户拦截一次 🚧），小助手就会自动把门户地址记在小本本上啦 📝✨！", "A29": "📋 复制「关闭系统自动弹窗」的魔法命令 🪄", "A30": "🧹 关掉系统登录弹窗（它经常赖着不走）", "A31": "✅ 已经帮你把系统弹窗关掉啦", "A32": "🤷‍♂️ 现在没找到系统弹窗（可能已经自己关了）", "B101": "😴 还没连上网呢", "B102": "🚶‍♂️ 现在处于「没刷卡认证」的状态，就像你人已经走进吉大校门了，但还没在闸机上刷校园卡一样 🪪。", "B103": "👇 轻轻点一下下面的「连接 / 登录」，小助手就会立刻帮你刷卡放行啦 🚀✨！", "B104": "🏃‍♂️ 正在快马加鞭连接中…", "B105": "🪪 正在跟学校的网关门卫大哥核对你的身份呢，就像门卫大爷眯着眼看一眼你的校园卡 👀，通常一两秒钟就放行啦 ⏱️✨！", "B106": "🎉 已稳稳连接！", "B107": "🛡️ 这条网络通道现在有 JLU Gate 替你寸步不离地守着，放心大胆地去网上冲浪吧 🏄‍♂️💖！", "B108": "🤝 已连接（目前是官方客户端在当家管事）", "B109": "🏠 官方的 Dr.Com 客户端正紧紧握着那条认证通道呢（它先一步占了端口），不过好消息是网络完全畅通，你现在可以正常上网哒 🌐✨！", "B110": "🔄 如果想把接力棒交给更轻快的 JLU Gate 来管：先去官方客户端里点退出 👋，再回咱们这儿点「连接」就好啦 ✨！", "B111": "🚧 官方客户端占着茅坑，但还没连上网 🙈", "B112": "📞 认证专用的端口被官方客户端死死捏在手里，偏偏它自己也没能认证成功——就像有人占着公共电话亭却一直没拨通电话一样，急死个人 😅💦！", "B113": "👉 快去彻底退出官方的 Dr.Com 客户端（别忘了检查菜单栏和后台叫 DrClientNS 的小尾巴进程哦 🧹），退干净后再来点「连接」就能满血复活啦 🚀！", "B114": "⏳ 正在乖乖等待网络就绪…", "B115": "🚗 电脑现在还没有可用的网线连接或 IP 地址呢，就像跑车还没开上高速公路匝道一样 🛣️。", "B116": "🔌 把网线插插紧（或者确认这块网卡已经拿到了 IP 地址），小助手一看到路通了就会自动帮你继续往前冲哒 🏃‍♂️✨！", "B117": "😭 哎呀，没能连上", "B118": "🧗‍♂️ 小助手刚才努力尝试过了，但很遗憾没能迈过学校网关这一关 🚧。", "B119": "👇 别灰心，看看下面贴心列出的原因；顺手改好后再点一下「重试」就能过关啦 💪✨！", "B120": "📞 学校官方客户端抢先占用了认证专用的「热线电话号码」（UDP 61440 端口），导致咱们的电话打不进去啦 🙈。", "B121": "🌐 网页认证需要浏览器出马：登录页面会在你的浏览器里弹出来，输完账号密码登录成功后，记得回咱们这儿点一下「已完成登录」哦 🙋‍♂️✨！", "B122": "🔄 本地回环（电脑自己跟自己说话 🗣️）", "B123": "🧠 系统内核自带", "B124": "🏠 127.0.0.1 只在咱们电脑内部自己传纸条用，数据包永远不会顺着网线跑出去的 🔒。", "B125": "🪄 由 VPN 或代理软件变出来的（当前没抓到具体是哪个软件进程在管 🕵️‍♂️）", "B126": "🪄 由「{…}」一手创建", "B127": "🚇 虚拟网卡（加密隧道）", "B128": "🚪 代理软件把它当成流量出门的总大门；万一它不小心把校园网段也抢走了，咱们的认证包就会迷路到不了学校网关哦 🚨！", "B129": "🍎 Apple 内部神秘接口", "B130": "⚙️ 苹果系统 / 芯片组自带（不是咱们能用手插拔的物理网卡哦 🙅‍♂️）", "B131": "📱 专门用来给苹果系统内部说悄悄话的（比如跟你的 iPhone 隔空互联、解锁之类 ✨），跟咱们连校园网冲浪没啥关系哈 🏖️。", "B132": "✈️ AirDrop / AirPlay 隔空直连通道", "B133": "📡 苹果系统专用（无线点对点直连，不是用来上网的口哦）", "B134": "🤝 只负责和附近的 iPad、iPhone 等苹果全家桶传照片投屏，不挑上网流量的大梁 ✨。", "B135": "⚡ Thunderbolt 雷雳桥接", "B136": "🔗 系统自动创建的（当你用雷雳线把两台 Mac 直接连在一起传文件时才用得上 💻⚡💻）", "B137": "💤 平时根本用不到它；如果哪天发现它居然被当成了默认上网出口，那说明系统的网络配置顺序肯定乱套啦 😵‍💫！", "B138": "📡 Wi-Fi（无线局域网）", "B139": "💻 电脑内置的无线网卡（或者是把有线转成无线的随身适配器 ✨）", "B140": "🌐 连 JLU.WIFI 时走这个口做网页认证；连 JLU.PC 时也是靠它来跑 Dr.Com 认证协议哒 🏃‍♂️✨！", "B141": "🔌 USB 外接有线网卡", "B142": "转换头 / 拓展坞上的外接 USB 网卡（注意：换个 USB 插口它就可能改名字 🎭，所以咱们全靠 MAC 地址来认准它 🎯！）", "B143": "⚠️ 当前还没有 IPv4 地址呢：多半是因为这根网卡刚插上去，还没来得及去系统设置里给它配好静态固定地址 📝。", "B144": "💡 换插口或者换新网卡后，系统里的接口名往往会变；但学校只认登记的 MAC 地址，所以一定要核对好 MAC 哦 🪪✨！", "B145": "⚡ 雷雳 / Thunderbolt 有线网卡", "B146": "🔌 内置或外接的高速有线网卡", "B147": "⚡ 雷雳 / Thunderbolt 高端扩展坞上的有线网口", "B148": "💻 系统内置或者扩展坞自带的有线网口", "B149": "⚠️ 当前还没有 IPv4 地址哦：先把网线插稳当，或者去给它配好学校分的静态地址，咱们才能开始认证呀 🛠️✨！", "B150": "📌 插网线冲浪时就靠它啦：记住填进去的 IP / 掩码 / 网关必须和学校开户通知单上分给你的一模一样哦 📋✨！", "B151": "🔌 有线网卡", "B152": "🌐 系统标准网络接口", "B153": "✅ 状态棒棒哒，随时可以用于校园网认证 🚀！", "B154": "🧩 其他系统接口", "B155": "⚙️ 系统底层自带", "B156": "🍃 和咱们平时上网冲浪完全无关，直接无视它就好啦 😎。", "B157": "🔒 已乖乖听话，锁定使用「{…}」出战 🎯！", "B158": "🤖 你还没填登记的 MAC 地址呢：小助手会在所有网卡里聪明地帮你挑一块最合适的（优先挑稳当的有线网卡哦 🔌✨）。", "B159": "😱 找遍了全身，也没有哪块网卡的 MAC 等于你在学校登记的 {…}（电脑里现有的网卡是：{…}）。快换回当初登记过的那块网卡/拓展坞，或者去学校自助平台改一下登记的 MAC 吧 🏫✍️！", "B160": "🎯 耶！已按 MAC 地址精准锁定目标网卡：{…}（{…}）✨！", "B161": "👯‍♂️ 咦？发现有多块网卡的 MAC 地址都长成登记的 {…} 这样呢！为了防止选错，建议你在下面手动点名指定其中一块哦 👇✨。", "B201": "🙈 哎呀，{…} 看起来不是一个合法的 IPv4 地址呢（应该是四段数字加三个点哦 🔢）", "B202": "📏 子网掩码的二进制位不连续哦：{…}（正常一般都是 255.255.255.0 这样哒 ✨）", "B203": "🚧 网关 {…} 迷路啦，它不在你填的 {…}/{…} 这个网段小区里面哦 🏘️！", "B204": "👯‍♂️ 网关地址可不能和咱们本机的 IP 一模一样呀（{…}），不然自己发给自己可出不去门哦 🚪💦！", "B205": "🪪 MAC 地址的格式不太对劲呢：{…}（应该是 6 组两位十六进制字符，比如 a1:b2:c3:d4:e5:f6✨）", "B206": "🚪 网关", "B207": "🙈 读不到这块网卡是怎么配置的；请拿出学校的开户通知单手动照抄固定地址吧 📝，千万别直接用 DHCP 自动分到的临时地址哦 🙅‍♂️！", "B208": "⚠️ 这块网卡现在处于 {…} 模式，身上的地址是自动领到的临时号牌，不能当成固定静态参数来用哦 🙅‍♂️。请手动照抄学校通知单上的地址吧 ✍️！", "B209": "🤔 系统里虽然设成了手动配置，但这块网卡身上目前还空空如也、没有 IPv4 地址呢 📭。", "B210": "🎉 太棒了！这块网卡当前就是手动配置模式，下面读出来的数字就是电脑实际正在用的静态参数，可以直接拿来用哦（当然，顺眼和学校通知单核对一下就更稳妥啦 👀✨）！", "B211": "✍️ 请输入你学校邮箱 @{…} 前面的那一段前缀吧 ✨。", "B212": "🔤 账号里面只能有英文字母和数字哦（只要填邮箱 @ 前面的前缀就行，别把整个邮箱地址都搬进来哈 🙅‍♂️✨）。", "B213": "👨‍🏫 哇，看起来是老师的账号呢：格式是姓名全拼（比如 zhangshanwu）。遇到同名同姓时学校会在后面加数字后缀，以您的实际邮箱前缀为准哦 📧。注意：这里的密码填的是您的统一身份认证密码哦 🔑✨！", "B214": "🎓 同学你好呀！学生账号的规律是 ＝ 姓氏全拼 ＋ 名字每个字的首字母 ＋ 4 位数字（2 位专业代码 ＋ 2 位入学年份），举个栗子：zhangcyy2122 🌰✨。", "B215": "🎒 识别成功！学生账号：专业代码 {…}，20{…} 年入学的小可爱/老学长 🎉！记住：这里填的密码是你的统一身份认证密码哦 🔑✨！", "B216": "💡 敲黑板！账号就是你学校邮箱 @{…} 前面的那串前缀，而密码则是大家最常用的统一身份认证密码哦 🔑： · 🎓 学生同学：姓全拼 + 名各字首字母 + 4 位数字（专业代码 2 位 + 入学年份 2 位），比如 zhangcyy2122； · 👨‍🏫 教职员工：姓名全拼，比如 zhangshanwu（同名时学校会加后缀，以邮箱实际前缀为准 ✨）。", "B301": "🍃 纯净直连（没有任何代理接管）", "B302": "🦸‍♂️ 代理已接管公网流量（不过校内网段依然乖乖走直连 🛣️✨）", "B303": "🌍 全局代理模式（连校园网段也被代理一锅端接管啦 🚨）", "B304": "🚇 TUN 虚拟网卡已开启，但还没出手接管默认路由 💤", "B305": "🤔 雾里看花，暂时无法判断", "B306": "⚪ 还未设置", "B307": "⚖️ 配置模式（按规则聪明分流 ✨）", "B308": "🌍 代理模式（全局统统走代理）", "B309": "🛣️ 直连模式", "B310": "🎬 当前场景", "B311": "（🕵️‍♂️ 实际探测到：{…}）", "B312": "🍃 所有网络流量都原汁原味地从物理网卡出门{…}，你的校园网认证包绝对不会被代理软件误吞掉，超稳当 🛡️✨！", "B313": "⚖️ 去往外面公网的流量已经由代理软件接管护送 ✈️，而咱们吉大校内网段的流量依然老老实实从 {…} 直接出门{…}，分工超明确 🤝✨！", "B314": "💡 冷知识时间：像 Shadowrocket（小火箭）或 Clash 这类聪明的软件，哪怕你表面上切到了「全局（Global）」模式，它们底层通常也会贴心地放行局域网和校内网段 🛣️，", "B315": "所以光查路由表是分不出你点的到底是「全局」还是「规则」哒——不过不管白猫黑猫，只要咱们的认证包没被迫绕远路，那就是大好事一桩 🎉✨！", "B316": "🚨 哎呀，连咱们学校的内部网段也被虚拟网卡一并接管拿走啦{…}！这意味着你的认证包得先去代理软件肚子里绕一圈才能出来🌀——至于能不能认证成功，全看这段绕路稳不稳当：", "B317": "⏱️ 如果代理软件手脚麻利、延迟极低还不丢包，那照样能蒙混过关认证成功 ✌️；可一旦代理稍微卡顿抖动或者排队，认证和保活心跳包一超时，就会被学校服务器无情判定为掉线中断哦 😭💦！", "B318": "🚇 系统里虽然看到了 TUN 虚拟网卡，但它还没把默认路由的方向盘抢过去{…}；可能是你的分流规则没匹配上，或者代理开关其实还没真正生效呢 🤔。", "B319": "🙈 没能拿到系统的路由表信息，这次没法帮你判断啦 🤷‍♂️。", "B320": "👍 当前状态棒棒哒，啥都不用改！如果你想挂着代理去看看外面的世界 🌍，随时可以在小火箭/Clash 里切到「配置（规则）」或「代理（全局）」模式哦 ✨。", "B321": "💖 这个分流状态对校园网认证最友好啦：保持原样完全不用改！万一哪天突然莫名其妙掉线，再来确认一下是不是代理规则不小心把 10.0.0.0/8 也给吞掉就行啦 🕵️‍♂️✨。", "B322": "🛠️ 在全局模式下，建议先去点一下「测认证通道延迟」⏱️：如果发现走代理比直连慢了一大截、或者出现了丢包 🐢，那就快把代理切成「配置（规则）」模式，并手动加一条规则把 10.0.0.0/8 设为直连吧（比如 Clash 写 IP-CIDR,10.0.0.0/8,DIRECT）✍️！当然，如果测出来延迟依然飞快，那继续开着全局也能凑合用，只是平时会稍微容易掉线一点点哦 🤏✨。", "B323": "🤔 如果你本意是想走代理上网的，快去检查下小火箭/Clash 的「配置」开关有没有真正打开、分流规则有没有写对；如果你只是想安安静静连个校园网，那现在这样就挺好哒 🍃✨！", "B324": "🔄 请移步到「网络详情」页面，点一下重新检测看看吧 🔍✨！", "B325": "📖💥 域名解析失败（找不到网址对应的门牌号 🙈）", "B326": "🔌💥 连不上目标服务器（敲门没人应 🚪）", "B327": "🔒💥 TLS 加密握手被无情拒绝", "B328": "🙅‍♂️ 服务器摆手拒绝了咱们的请求", "B329": "⏱️ 等得花儿都谢了，超时取消 🥀", "B330": "🏫 仅限校内网访问", "B331": "🌍 校内校外都能随时开", "B332": "🟢 畅通无阻（HTTP {…}）🎉", "B333": "🟠 服务器回了个状态码 {…} 🤔", "B334": "🔴 服务器冷酷拒绝", "B335": "🔌 网卡身上还没有可用的 IP 地址呢，效果就跟没插网线一模一样 🙈。", "B336": "👉 快检查下网线插紧了没，或者去系统设置里确认这块网卡已经稳稳拿到了 IP 地址吧 🛠️✨！", "B337": "⚪ 目前还没有检测结果哦 🐣。", "B338": "👆 点一下「开始排查」让小助手帮你看看吧 🩺✨！", "B339": "🎉 哇哦！测试的所有站点全都一路绿灯畅通无阻，你的网络健康得不得了 🏄‍♂️💖！", "B340": "🏖️ 完美状态，啥都不用处理，安心冲浪吧 ✨！", "B341": "🤔 发现有网站打不开，而且连咱们学校的认证服务器（10.100.61.3）都叫不应没回执——看来问题多半出在咱们校内网这一段路哦 🏫💦。", "B342": "👉 先确认你现在是不是真的连着校园网（插着网线或连着 JLU.PC），或者喝口水稍等片刻再试 🍵；如果好半天都这样，那八成是学校网络中心的认证服务器正在维护打盹呢 😴🛠️。", "B343": "📖 绝大多数打不开的网站都齐刷刷卡在了「域名解析（DNS）」这一步：也就是网址没能被成功翻译成 IP 数字地址 🙈💦。", "B344": "💡 试试去把系统的 DNS 换成公共 DNS（比如阿里的 223.5.5.5）吧 🛠️；如果你开着代理软件，也顺手检查一下它的 DNS 设置，看看是不是不小心把解析请求打回不通的本地路线啦 🕵️‍♂️✨！", "B345": "🔒 能顺着网线摸到服务器大门，但在进行 TLS 加密握手对暗号时被拒绝了——说明半路上有网络设备在拦截，或者是网站的安全证书不对劲 🚧🧐。", "B346": "👉 如果你正开着代理软件，先把它关掉试一次 📴；要是关了代理还是握不上爪，那多半就是外面的网络运营商或防火墙在半路拦截啦 🛡️💦。", "B347": "🤝 网络连接和加密握手全都顺利通过啦！只是对面的网站服务器自己闹脾气，给你回了个拒绝状态码（4xx / 5xx）😤。", "B348": "☕ 这种通常是对面网站自己在抽风维护或者限流，跟你这台电脑和代理设置都没关系，换个时间再去逛逛就好啦 🏖️✨！", "B349": "🐼 国内网站刷得飞起，但国外网站全军覆没：检测到你的代理软件明明在跑，但它的出口节点好像没能把流量真正带出国门哦 ✈️💥。", "B350": "👉 快去代理软件里换个生龙活虎的节点试试 🔄，或者看看是不是机场套餐流量用光啦 💸；当然也可以先关掉代理，安心享受校内直连的高速冲浪 🏄‍♂️✨！", "B351": "🐼 国内网站一路绿灯，国外网站全都打不开，而且检测到你压根没开代理软件——哈哈，这就是最标准的「没开代理」状态啦 😂✨！", "B352": "💡 当你需要去逛 GitHub 等境外网站时，记得打开你的代理软件哦 ✈️；如果只是在国内和校内冲浪，现在这样就完全不用管啦 🏖️！", "B353": "🌍 外面的公网网站都能正常逛，偏偏吉大校内系统（{…}）进不去——因为它们是害羞的「仅限校内网」系统呀 🔒（注：学生邮箱本来就是校内外都能开的，所以邮箱能开可不算数哦 ✉️😜）！", "B354": "🌉 如果你现在人在校外（比如连着家里 Wi-Fi 或手机热点），请先登录学校的 WebVPN 再去访问它们；如果你明明就在寝室校园网里，那就先确认一下是不是校园网认证掉线啦 🔄✨！", "B355": "💥 好几个网站连最基础的 TCP 连接都建立失败：说明往外走的出口这一段路直接断掉啦（可能是代理节点挂了，或者上游网络拔线了 🔌💦）。", "B356": "👉 先在代理软件里换个其他节点试试 🔄；要是换了还不行，干脆先把代理关掉，用纯净直连试试看咱们校园网本身是不是正常的 🕵️‍♂️✨。", "B357": "🔍 顺手确认一下校园网是不是已经成功认证在线；也可以去「详情」页里先 Ping 一下网关看看路通不通哦 🏓✨。", "B358": "🤔 有零星几个网站打不开，但它们失败的原因五花八门，没有集中在同一个环节上 🧩。", "B359": "👇 咱们可以低头看看下面每个网站具体卡在哪一步，再来对症下药，决定是去查 DNS、换代理节点，还是单纯怪那个网站自己抽风吧 🩺✨！", "B401": "📭 尚未登记", "B402": "❓ 神秘未知", "B403": "🪪 敲黑板！学校网关是个认死理的「认卡不认人」主儿（按 MAC 地址识别设备）：你当前这块网卡{…} 的物理地址是 {…}，但你账号档案里登记造册的却是 {…} 哦 🙈！ 要知道，插网线走的是有线/USB 网卡的 MAC，而连 JLU.PC 走的则是电脑内置 Wi-Fi 网卡的 MAC——这俩可不是同一块硬件，也不能互相冒充 🙅‍♂️。 如果你想改用现在这个网络冲浪，得先去学校自助平台把登记的 MAC 修改成 {…}才行哦 ✍️（友情提醒：改完之后，原来绑定的那块网卡就暂时不能用来认证啦 🔄）！", "B404": "（🙈 读不到硬件物理地址呢）", "B405": "（📭 还没填登记地址）", "B406": "🎭 抓到一只伪装者！苹果系统现在给这块网卡披上了一层「私有/随机 MAC」马甲：{…}（只要看第一组第二个字符是 2 / 6 / a / e，就属于系统瞎编的随机地址 🕵️‍♂️）， 而这块网卡真正的出厂真身地址其实是 {…}，你在学校档案里登记的则是 {…}。 别慌，咱们有三种锦囊妙计可以搞定它 💡： 1️⃣ 最推荐 🌟：去苹果「系统设置 ⚙️ → 网络 → 点这块网卡 → 详细信息 → 硬件 / Wi-Fi」里，把「私有无线局域网地址 / 随机硬件地址」关掉，让它恢复出厂真身； 2️⃣ 懒人魔法 🪄：直接在咱们 App 的设置里打开「用登记的 MAC 认证」开关（发给学校的认证信件里会自动填上登记值，同时不去动系统网卡本身 ✨）； 3️⃣ 下下策 🙅‍♂️：去 ip.jlu.edu.cn 自助平台把学校登记的 MAC 改成当前这个随机地址（极其不推荐！因为哪天重连或者换个网，系统一高兴又会再换个新的随机地址，到时候又得断网啦 😭）。", "B407": "📡 注意啦！连 JLU.PC 无线网时，必须使用这台电脑内置 Wi-Fi 网卡的 MAC 地址来认证哦。如果你之前在学校平台登记的是外接 USB 网卡或插网线网口的 MAC， 在这儿认证是一定会碰壁失败的 🚧——你需要先去 ip.jlu.edu.cn 自助平台，把登记的 MAC 改成现在这块 Wi-Fi 网卡的地址才行哦 ✍️（注意：改完之后，原来插网线的那个口就会失去认证资格啦 🔄）！", "B408": "🎉 连上 JLU.PC 后，系统常常会自动跳出一个 login.jlu.edu.cn 的欢迎网页，这是咱们校园网的门户引导页（完全属于正常现象哈 🤗）。 你直接随手把它关掉就行 ✖️：因为核心的认证工作已经由咱们 JLU Gate 在后台悄无声息地搞定啦 🛡️，千万不需要在那个网页里再去下载老旧的官方客户端咯 🙅‍♂️✨！", "B409": "🙅‍♂️ 学校服务器摇了摇头，觉得当前这个 MAC 地址不属于你的账号档案呢。苹果 Mac 电脑的硬件 MAC 是出厂就焊死在网卡里的，没法靠软件随便改掉 🛠️： 请去 ip.jlu.edu.cn 自助平台核对或修改一下登记的 MAC 地址 ✍️，或者把你当初登记过的那个 USB 网卡/拓展坞重新插回来吧 🔌✨！", "B410": "📱 JLU.WIFI 规定同一个账号最多只能同时让 {…} 台设备在线冲浪 🏄‍♂️。一旦有新设备登录挤进来，就会像排队买奶茶一样，把最早登录进来的那台老设备给无情踢下线 🦵💥！ 你刚才的在线会话，很可能就是这么被你自己的另一台手机或平板给挤掉的哦 🙈✨。", "B411": "🔄 如果你现在点重新登录，就会把这台电脑重新排到在线队列的最末尾，同时顺脚踢掉当前队列里排在最前面的那台旧设备 🦵——如果那恰好是你正在看剧的平板或手机，它可就要瞬间断网咯 📱💦！", "B412": "💻 本机提示：在 {…} 台设备的名额上限之外，现在点击登录会让你重新排到队尾接管网络哦 🔄。 {…}", "B413": "💡 小科普：每次刚连上新 Wi-Fi 时自动弹出来的那个小网页窗口，其实是苹果 macOS 系统自带的「捕获门户助手（Captive Network Assistant）」🤖，是由系统底层直接触发的，咱们 App 也没法半路拦截它 🤷‍♂️。 不过别管它！只要咱们的程序在后台飞快地帮你完成了认证 ⚡，那个小窗口察觉到网通了，自己就会识趣地乖乖关掉啦 👋✨！", "B501": "⚪ 还没检测过呢", "B502": "✍️ 刚刚手动输入的", "B503": "💖 已妥善保存（而且之前成功登录过哦 ✌️）", "B504": "🤔 已保存（但还没上场验证过 🐣）", "B505": "😭 已保存（但上次被服务器拒绝了 💔）", "B506": "🤖 自动模式（还没出动探测 🕵️‍♂️）", "B507": "💻 本机 {…}", "B508": "🎉 当前已经在网上冲浪啦（虽然还没在咱们这儿配置账号 🏄‍♂️）", "B509": "🛡️ 为了防止连环报错，不再自动使用旧密码，这就带你去重新输入一次 ✍️", "B510": "🔑 为了避免用错密码被服务器拉黑，请重新输入一次正确的密码吧 ✨！", "B511": "🙈 填的服务器地址格式不太合法哦", "B512": "🚀 已经用上次贴心记在小本本上的门户地址帮你打开啦 📖✨！", "B513": "🕵️‍♂️ 正在努力嗅探门户地址中… ⏳", "B514": "🚀 小火箭 / Clash 等代理", "B515": "🚪 经由默认总出口", "B516": "🔌 哎呀，有线网卡 {…} 身上还没有 IP 地址呢 📭。快把学校通知单上分的静态参数填进来（或者去系统设置里把网卡改成 DHCP 自动获取），咱们再来连接吧 🛠️✨！", "B162": "🟡 认证还在，但外网确实不通",
    "B163": "🧗‍♂️ 和学校的连接还维持着，可是外面的网页连续几次都打不开——十有八九是流量被全局模式下的代理截住啦。",
    "B164": "👇 先点下面的「再试一次」重新连；要是还不行，就临时把代理切回「规则模式」再试哦 💪✨！",
    "C01": "🙋‍♂️ 这里需要你搭把手处理一下；搞定后点「重试」就能继续冲浪啦 🏄‍♂️✨！", "C02": "🔄 重试一下", "C03": "📊 看看网络详情", "C04": "✖️ 关闭", "D01": "📊 网络详情大透视", "D02": "🔄 刷新一下", "D03": "⏳ 正在努力读取中…", "D04": "🦸‍♂️ VPN/TUN 已接管流量", "D05": "🍃 VPN/TUN 未接管", "D06": "· ⚠️ DNS 被代理悄悄劫持啦", "D07": "🚀 代理模式（对照小火箭/Clash 等）", "D08": "✅ 和你设置的选择完全一致哦！", "D09": "🤔 咦，和你在软件里选的好像不太一样呢", "D10": "🕵️‍♂️ 正在仔细判断中…", "D11": "👉 你在代理软件里选的是：", "D12": "🍃 没发现 utun 虚拟接口：说明当前没有代理或 VPN 在抢方向盘（路由）哦 🚗✨。", "D13": "🚪 默认总出口", "D14": "🪪 认证流量专属出口", "D15": "🔌 有线网口", "D16": "📡 无线 Wi-Fi", "D17": "🪪 认证流量", "D18": "🟢 已启用", "D19": "⚪ 未启用", "D20": "🏭 出厂真身 MAC {…} ← 认证实际用的是这个哦（虽然系统现在披着私有/随机地址的马甲 🎭）", "D21": "🔗 链路本地地址 {…}", "D22": "🙈 没找到物理有线网口呢", "D23": "🧭 路由与 DNS 指路牌", "D24": "🛣️ 默认路由", "D25": "{…}（下一跳网关 {…} 🦘）", "D26": "📖 系统 DNS", "D27": "（🙈 读不到呢）", "D28": "💡 系统当前的 DNS 是 198.18.x.x（这是代理软件生成的 fake-ip 假地址 🎭）。不过别担心，咱们程序的探针不走它，会自己直接发 UDP 查询哒 🚀！", "D29": "⏱️ 认证通道延迟（UDP 61440 来回跑一圈 🏃‍♂️）", "D30": "💡 开着全局代理到底能不能稳稳认证，全看这条小路通不通畅——光看模式名字可不准哦 🧐！咱们用直连和走代理分别实测 3 次真实的 challenge 包看看 🎯：", "D31": "⏳ 正在掐表测量中…", "D32": "🏃‍♂️ 测测认证通道", "D33": "🏓 Ping 测试（TCP 握手延迟）", "D34": "👇 点下面的「开始 Ping」测一测去网关和公网来回要多久；还能顺便对比一下走 VPN 会多花多少时间哦 ⏱️✨！", "D35": "🏓 开始 Ping！", "D36": "🚀 飙车测速（HTTP 下载，直连 vs VPN 大比拼 🏎️）", "D37": "咱们会分别用「网口直连」和「当前默认出口（含 VPN）」各下载一小段数据比比速度 🏁，单位是 Mbps 哦 ✨。", "D38": "⚠️ 网口直连测速暂不可用：可能是被校园网关拦住了 🚧，或者这个测速点只欢迎代理流量通过哦 🤔。", "D39": "🏎️ 正在全力测速中…💨", "D40": "🚀 开始测速", "D41": "📋 复制全部信息", "D42": "✖️ 关闭", "E01": "📦💥 认证报文格式不对劲（{…}）", "E02": "👽 收到了一封看不懂的神秘报文：类型 0x{…} 子类型 0x{…}，长度 {…}", "E03": "📏 {…} 写得太长啦，最多只能装下 {…} 个字节哦 🙈", "E04": "📭 尚未登记 MAC", "E05": "🪪💥 网卡 MAC 地址对不上号：你在学校档案里登记的是 {…}，但当前出战的接口却是 {…} 🙈。如果换了新的 USB 网卡或拓展坞，一定要先去学校自助平台把新 MAC 登记上去才能用哦 🏫✍️！", "E06": "📭 接口 {…} 身上空空如也，还没有 IPv4 地址呢。请先去苹果「系统设置 → 网络」里给这块网卡配好学校分的固定静态地址吧（记住：静态认证可不接受 DHCP 自动分的地址哦 🙅‍♂️✨）！", "E07": "🔌💔 网卡 {…} 突然断开连接啦（是不是网线松了或者不小心拔掉了拓展坞呀 🤔？）。把它重新插紧后，小助手会自动帮你秒重连哒 🔄💖！", "E08": "⚠️ 接口 {…} 目前还在偷懒使用 DHCP 自动获取地址，还没改成手动配置呢 🛠️。学校的静态认证规矩严，不接受 DHCP 临时地址哦，快去改一下吧 ✍️！", "E09": "🧐 {…} 和档案里记的不一致哦：按理说应该是 {…}，但现在检测到的是 {…} 💦", "E10": "😴 呼叫学校认证服务器 {…} 完全没反应（无响应）。请先检查一下网线插好了没、静态 IP 和网关有没有抄错吧 🔍🔌！", "E11": "🚨 抓到代理软件把咱们校园网段也给接管抢走啦（当前出口是 {…}）🕳️！这会让认证包迷路的，快去代理软件的分流规则里把 10.0.0.0/8 设为直连（DIRECT），或者先把全局路由关掉吧 🛠️✨！", "E12": "🤝 官方的 Dr.Com 客户端{…}正紧紧握着认证通道呢（它抢先一步占用了本地 61440 端口）——不过这通常说明它已经在尽职尽责地替你连上网啦 🌐✨！", "E13": "🔄 如果你想换咱们更轻快好用的 JLU Gate 来接管网络：先去官方客户端里面点退出登录 👋；要是退了之后端口还被霸占着，就去活动监视器里把它的后台小尾巴进程 DrClientNS 彻底关掉就行啦 🧹✨！", "E14": "📞💥 哎呀，校园网认证专用的那个「热线电话分机号」（本地 UDP 61440 端口）已经被别的程序捷足先登占走啦{…} 🙈！", "E15": "💡 十有八九是学校官方的 Dr.Com 客户端干的，先把它彻底退出去，咱们就能顺利接管啦 🚀✨！", "E16": "🏞️ 检测发现当前连的网络好像不是吉大校园网哦（{…}），小助手先乖乖待命啦 💤", "E17": "🛠️ 哎呀，这种接入方式咱们目前还没学会支持呢：{…} 🙈", "E18": "⏱️💔 等得花儿都谢了，学校服务器还是没回信（回应超时：{…}）🥀", "E19": "🚧 网络通道出现了一点小异常：{…} 💦", "E20": "🛑 操作已取消", "E21": "🔄 学校服务端喊话：这次要求必须用 DHCP 动态获取地址哦！", "E22": "🪪💥 MAC 地址校验没通过", "E23": "🥵 学校服务器现在太忙啦，忙得满头大汗", "E24": "🔑💥 密码不对哦", "E25": "💸 网费余额不足啦", "E26": "🥶 糟糕，账号被冻结停机了", "E27": "🏠💥 IP 地址对不上号（不匹配）", "E28": "🪪💥 MAC 地址对不上号（不匹配）", "E29": "📱💥 同时在线的设备数量超标啦", "E30": "🙅‍♂️ 服务器拒绝了你的登录凭据（错误码 0x15）", "E31": "💥 IP 地址和 MAC 地址全都对不上号！", "E32": "🔄 必须使用 DHCP 动态地址", "E33": "🪪 当前这台电脑出战的网卡，和你账号绑定的那块不一样哦：请确认你插的是当初在学校登记过的那块网卡（而且没有开启系统的随机/私有 MAC 伪装 🎭）！", "E34": "🥵 学校认证服务器现在排队的人太多、有点过载喘不过气啦！完全不用改任何配置，咱们喝口水稍等片刻 🍵，小助手会自动帮你重试哒 🔄✨！", "E35": "🔑 快核对一下你的校园网（统一身份认证）密码是不是输错啦；如果你前两天刚在网页上改过新密码，记得在咱们这儿也同步更新一下哦 ✍️✨！", "E36": "💸 你的校园网账户余额见底啦！快去自助平台充点网费，喂饱它就能立刻恢复冲浪咯 💰🏄‍♂️！", "E37": "🥶 你的校园网账号目前处于停机或冻结状态呢，这得联系学校的大数据和网络管理中心老师帮忙解冻哦 📞🏫。", "E38": "🏠 这台电脑现在的 IP 地址和你账号绑定的固定 IP 不符哦：快检查一下网线是不是插错了寝室墙上的端口 🔌，或者是不是该改成自动获取 IP 呀 🤔？", "E39": "📱 你账号名下同时在线的设备数量已经顶到天花板上限啦！先去其他手机或电脑上注销退出一台，就能把名额腾出来咯 🔄✨。", "E40": "💡 在咱们吉大校园网里，报这个 0x15 错误码通常都是因为「密码填错了」🔑（开源社区的 jlu-drcom-ng 前辈们在代码里也是这么标注哒 🤓）；", "E41": "当然也有极小概率是学校服务端升级改了脾气。建议你先去网页版统一身份认证试登一下确认密码没错 🌐，再回咱们客户端里重新输入一次吧 ✍️✨！", "E42": "👉 请去苹果「系统设置 → 网络」里，把这块网卡的配置方式改成「使用 DHCP（自动获取地址）」，然后再回来点重试就好啦 🔄✨！", "G01": "🎉 选 JLU.WIFI 的同学看过来：不用填 IP 和 MAC 哦！", "G02": "🤔 看着参数一脸懵？走，去校园网自助平台查一查 🔍！", "G03": "它是超省心的网页认证 🌐，地址由 DHCP 自动分发；只要用「统一身份认证」的账号密码在弹出的网页里登一下就好啦 🥳！", "G04": "⚠️ 连之前先瞪大眼睛看清楚 Wi-Fi 名字是不是 JLU.WIFI（大写字母、中间带个点 🟢），千万别在名字很像的野鸡网络里输账号呀 🛡️！", "G05": "💡 固定 IP 和网关藏在「查询信息」里；登记 MAC 则在「变更 MAC」里。要是死活连不上，也有可能是网费余额告急啦 💸！", "G06": "🌐 传送门：打开 ip.jlu.edu.cn/pay 🚀", "G07": "🔼 收起小卡片", "G08": "📖 看看详细步骤", "G09": "1️⃣ 先连上 JLU.WIFI（名字要一字不差哦），然后点菜单栏上的小图标 → 点「登录」🚀，", "G10": "2️⃣ 在跳出来的网页里，填上你「统一身份认证」的账号和密码就搞定啦 ✌️✨！", "G11": "🎈 完全不用填 IP / 掩码 / 网关 / MAC——地址都是自动发的，网页认证只认你的账号不认人 😎！", "G12": "🏫 自助平台平时主要是用来查查网费 💰、办个开户 📝、或者看看有哪些设备在线的 👀。", "G13": "🔑 登录它要用：校园卡号（就是录取通知书上那串长数字，比如 20220501324）＋ 6 位数字密码 ＋ 验证码 🔢✨。", "G14": "🔍 进去后点「查询信息」：你的 IP、网关、DNS 全都在这儿排排坐呢——不过这里没有 MAC 地址哦 🙅‍♂️。", "G15": "🪪 想看或修改登记的 MAC？得走旁边另一个门：点「变更 MAC」进去就能看到或修改啦 ✍️✨！", "G16": "😮 如果列表里空空如也、没有你的 IP：先退回主菜单点「网络开户」🎉，开通成功后再回来查就有啦！", "G17": "🤯 傻傻分不清的「三种密码」大揭秘！", "G18": "💻 怎么找自己电脑的 MAC 地址？", "G19": "💡 友情提示：如果你其实连的是 JLU.WIFI，那这些静态参数一个字都不用填！因为它是动态地址的网页认证哈 🏖️✨。", "G20": "💳 1. 吉大 V 卡（校园卡）", "G21": "账号 = 录取通知书编号；密码 = 6 位纯数字 🔢。去校园网自助平台查信息、交网费用的就是这套哦 💰！", "G22": "📧 2. 吉大邮箱", "G23": "拥有独立的一套密码 🔒，专门用来登录学校邮箱收发信件 ✉️；不过它的账号前缀和统一账号是一模一样的 ✨。", "G24": "🔑 3. 统一身份认证（最常用 🌟）", "G25": "查教务、连 VPN、还有咱们这个 JLU Gate（包括 JLU.WIFI 网页登录）用的全都是这套王牌账号密码 👑✨！", "G26": "🔌 找有线网卡的 MAC：", "G27": "打开苹果「系统设置」⚙️ → 点「网络」🌐 → 点你插着的那根有线网卡（USB 转接网卡也在这一栏哦）→ 点「详细信息」→ 就能看到「MAC 地址」啦 👀✨！", "G28": "📡 找 Wi-Fi 的 MAC：打开「系统设置」⚙️ → 点「Wi-Fi」→ 点已经连上的校园网（JLU.WIFI / JLU.PC）旁边的「详细信息 / ⋯」按钮 → 就能找到 MAC 啦 🎯！", "G29": "⚠️ 注意咱们要的是这块网卡出厂自带的真实物理地址哦！如果系统贴心过头、默认开了「私有无线局域网地址 / 随机 MAC」🎭，", "G30": "记得先把它关掉 🙅‍♂️，或者在咱们 App 的设置里勾上「用登记的 MAC 认证」也行 🪄✨！", "G31": "💸 怎么都连不上？摸摸口袋，是不是欠费啦 🙈", "G32": "校园网很宽容的，余额 -10 元、0 元都还能让你继续冲浪 🏄‍♂️；但一旦跌到 -20 元就会无情断网啦 ✂️（有线 / JLU.PC / JLU.WIFI 统统断掉哦）。", "G33": "💰 充值档位只有 20 / 40 / 100 元三档，钱会直接从你的校园卡余额里划走——注意啦！如果已经欠了 20 元，只充 20 元进去变成 0 元是不会复机的 😱，", "G34": "必须一口气充 40 元，让余额变成正数的 20 元，网络才会重新向你敞开怀抱哦 🤗✨！", "G35": "🔍 这些余额和账单数字都在自助平台的「查询信息」里，用你的校园卡号 + 6 位 V 卡密码就能登进去看啦 👀。", "G36": "🚀 打开自助平台去瞅瞅", "G37": "🌱 萌新必看小贴士 ✨", "G38": "📸 换寝室的时候，学校可能会弹出一个「用户迁移」页面：上面写着网卡的物理地址（MAC）、原来的 IP 和迁移之后的 IP——记得截图保存下来 📷，后面填网络参数、去自助平台登记 MAC 都要用到。", "M01": "耶！🎉 目前没有需要处理的网页认证哦 🏖️✨", "M02": "🔙 溜回去", "M03": "哎呀，这里需要你搭把手处理一下 🙋‍♂️；搞定后点「重试」就好啦 🔄✨！", "M04": "🌐 小路（链路）", "M05": "🏠 本机 IP", "M06": "学校分给咱们这台电脑的专属门牌号 🪧✨", "M07": "🟢 稳稳在线中", "M08": "这期间小助手一直在后台默默帮你续命认证 💓，完全不用你操心喔 ☕️✨！", "M09": "🚪 出口", "M10": "认证包从哪张网卡溜出去 🏃‍♂️；走代理不一定坏事，但如果太慢或丢包 🐢，会被学校误判掉线哦 🥺", "M11": "🔌 插网线的那种，稳如泰山 ⛰️✨！", "M12": "📡 学校的无线信号，需要用 Wi-Fi 网卡的身份来刷卡认证哦 🪪✨", "M13": "🌐 网页登录那种，呼叫浏览器出马 🧭✨！", "M14": "🤖 自动模式：先帮你探探路 🕵️‍♂️，再决定走哪条道最顺畅 ✨！", "M15": "⏰ {…} 起 · 陪伴你 {…} 啦 ✨", "M16": "✍️ 填好账号密码（哪怕断线也会自动帮你秒重连哦 🔄💓）", "M17": "👋 先撤啦（下线）", "M18": "🚀 冲鸭！登录！", "M19": "🔄 再试一次", "M20": "🔑 重新输入密码", "M21": "哎呀，代理把校园网段也包揽啦 🚧，咱们需要先加一条直连小抄近道 🛣️：", "M22": "📋 复制魔法命令", "M23": "🙋‍♂️ 我跑完命令啦，重新检测！", "M24": "📱 JLU.WIFI 最多只能同时让 {…} 台设备在线哦 👯‍♂️", "M25": "🤺 重新把在线名额抢回来！", "M26": "🌐 打开网页登录页", "M27": "🛠️ 重新设置一下…", "M28": "🏭 改用出厂自带 MAC {…} ✨", "M29": "🏫 打开自助平台（去改登记的 MAC ✍️）", "M30": "同一账号同一时间只能有一台设备在线哦 ☝️。想让这台电脑上线？去另一台设备上退一下（或者喝口水等 30 秒自动释放 🍵），再点重试就好啦 🔄！", "M31": "咦？这个 MAC 已经被别的设备捷足先登啦 😱！如果你换了网卡或用了共享的便宜网卡，快去学校平台核对一下登记信息吧 🔍🏫！", "M32": "⚙️ 设置", "M33": "🧭 宝藏站点", "M34": "📊 详情", "M35": "🩺 诊断", "M36": "🏥 体检", "M37": "🚪 退出", "M38": "🌟 更新：去 GitHub 看看有没有新鲜出炉的版本 📦", "M39": "🔍 正在努力搜寻最新版本… ⏳", "M40": "已是最新最棒版本 🎉✨", "M41": "叮咚！🔔 发现新版本 {…} 啦：点一下「更新」就能自动下载并换新装哦 👗✨！", "M42": "⬆️ 立即更新", "M43": "⏳ 正在瞅瞅…", "M44": "🔄 再查一次呗", "N01": "👋 断开连接", "N02": "🚀 立即连接", "N03": "🔄 刷新状态", "N04": "🏥 网络体检", "N05": "⚙️ 设置…", "N06": "🚪 退出 JLU Gate", "N07": "📏 屏幕宽度 {…}，中线位置 {…}", "N08": "🧹 撤回位置偏好、恢复默认摆放", "N09": "👈 哎呀，图标跑到屏幕左半边去啦", "N10": "💖 关于 JLU Gate", "N11": "🛡️ 默默守护你的校园网时刻在线 ✨", "N12": "🎉 耶！已成功切换到最新版本！", "N13": "👋 旧版本（build {…}）已经功成身退，现在是由崭新的 build {…} 为你服务哦 🚀✨！", "N14": "🙋‍♂️ JLU Gate 需要你搭把手处理一下哦", "N15": "📦 发现当前的 App 还没住进系统的 /Applications（应用程序）文件夹里，没法自动帮你替换更新呢 🥺。请先把 JLU Gate 拖进「应用程序」文件夹安家，再来体验丝滑的一键更新吧 🏠✨！", "N16": "😭 下载失败啦：{…}", "N17": "📦💥 解压失败啦：{…}", "N18": "📥 正在努力下载新版本中… ⏳", "N19": "📦 正在拆包解压中… ✨", "N20": "🤔 咦？下载的压缩包里居然没找到 .app 程序呢", "N21": "🔄 准备退下旧版本并换上新装… 👗✨", "N22": "🌟（比现在用的版本更新哦！）", "N23": "🍂（比现在用的版本旧，建议顺手删掉省空间哦 🗑️）", "N24": "⚠️ JLUGate: 写日志文件时绊了一跤 {…}", "N25": "🎒 JLUGate: 随身携带的便携副本不注册开机自启哦 ✨", "N26": "⚠️ JLUGate: 设置开机自启登录项时失败啦 {…}", "N27": "🔍 正在核对安装包的完整性… 🧾", "N28": "🧾 安装包校验没通过（可能下载时被截断或被替换），已取消这次更新。请重新试一次；如果反复出现，去发布页手动下载。", "P01": "🩺 这里体检的是你平时用浏览器上网真正会走的那条路：看看出口 IP 是哪儿、WebRTC 会不会漏底、DNS 有没有跑偏、还有烦人的人机验证能不能刷出来 🧩✨。", "P02": "🌐 到底能不能愉快上网（含校内各大系统 🏫）", "P03": "✨ 一进这个页面小助手就会自动帮你开始体检啦；下面的按钮是留给你随时复查重试用的 🔄！", "P04": "🏫 校内专属系统（教务和通知只有校内能开 🔒；邮箱则是校内校外都能随时打开哒 ✉️✨）", "P05": "🩺 正在认真体检中… ⏳", "P06": "🔄 重新体检一次", "P07": "🚪 出口 IP", "P08": "🤖 人机验证（Captcha）", "P09": "（📺 哔哩哔哩 B 站聪明地走了另一条分流小路 🛤️）", "P10": "⚠️ 咦，各个检测源报出来的国家不一样呢（{…}）：这大概率是个广播 IP 或者中转节点哦 📡✨", "P100": "🇯🇵 日本", "P101": "🇰🇷 韩国", "P102": "🇰🇷 韩国", "P103": "🇸🇬 新加坡", "P104": "🇺🇸 美国", "P105": "🇭🇰 中国香港", "P106": "🇹🇼 中国台湾", "P107": "🇬🇧 英国", "P108": "🇩🇪 德国", "P109": "🇷🇺 俄罗斯", "P11": "🧭 DNS 与 IP 出口默契度：", "P110": "🇨🇦 加拿大", "P111": "🇦🇺 澳大利亚", "P112": "🇳🇱 荷兰", "P113": "🇫🇷 法国", "P114": "🙈 没能拿到 DNS 的出口地址（可能是 DNS 被代理软件严密接管了，或者干脆连不上），这次就没法帮你比对啦 🤷‍♂️。", "P115": "🎭 系统 DNS 目前被代理软件接管啦（解析出来的出口是 {…} 这个 Fake-IP 假地址），", "P116": "所以咱们看不到它背后真实的物理位置——别担心，这可不是泄漏或不一致，只是穿了隐身衣比不出来而已哦 🧥✨！", "P117": "🌟 太完美啦！你的 DNS 解析出口和最终的 IP 出口完完全全是同一个地址，在各大网站的风控眼里看起来就像本地居民一样自然丝滑 🏡💖！", "P118": "🤔 缺少国家地理位置信息，暂时还没法帮你比对呢 🕵️‍♂️。", "P119": "✅ 你的 DNS 出口({…}) 和 IP 出口({…}) 都在同一个国家/地区，步调一致，触发风控的风险很低哦 👍✨！", "P12": "🏎️ 带宽速度三档大比拼", "P120": "🚨 哎呀！你的 DNS 解析是从 {…} 冒出来的，但实际流量的 IP 却远在 {…}——俩人隔着十万八千里呢 🌍💦，", "P121": "这样「身首异处」最容易被精明的风控系统一眼识破判定为代理异常 👀，有时候甚至比单纯用机房 IP 还容易被封号或弹验证哦 😱！", "P13": "🛣️ 纯直连", "P14": "🚪 默认出口（含代理）", "P15": "💻 本地代理端口", "P16": "💻 本地代理 127.0.0.1:7890", "P17": "🏎️ 正在飙车测速中… 💨", "P18": "🚀 测速", "P19": "💡 没找到本地代理端口哦：如果你开的是 TUN 全局虚拟网卡模式，那第二档测出来的就已经是最终速度啦，不用再测第三档咯 ✌️✨！", "P20": "🎯 已经自动帮你嗅探到代理端口 {…}（{…}）啦；要是不对也可以手动改哦 ✍️！", "P21": "🌐 在浏览器里打开校园网门户看看", "P22": "🏡 住宅 / 运营商原生 IP：最受 Claude、Netflix 等傲娇流媒体和 AI 站点的欢迎啦 💖✨！", "P23": "🏢 机房数据中心 IP：很多警惕性高的网站看到它会直接摆手拒绝 🙅‍♂️，或者疯狂弹人机验证考你眼力 🧩💦", "P24": "📱 移动蜂窝网络 IP：平时表现还不错 👍，就是偶尔可能会被限速哦 🐢", "P25": "🤔 查到的归属信息太少啦，暂时还判断不出它是哪种类型的 IP 呢 🕵️‍♂️", "P26": "👆 点上面的「开始检测」，小助手就会去帮你打听这个出口 IP 的户口本和类型（到底是温馨民宅 🏡 还是大机房 🏢）✨", "P27": "🗣️ 正在挨家挨户问不同的网站：「嘿，在你眼里我是从哪儿来的谁呀？」… 🔍", "P28": "👆 点一下「开始检测」，咱们去问几个主流网站同一个哲学问题 🧐✨", "P29": "🧼 出口 IP 纯净度大考验", "P30": "🚨 糟糕，已被公开黑名单标记为代理 IP 啦", "P31": "📍 地理位置", "P32": "🏷️ 归属运营商 (ASN)", "P33": "🧬 IP 类型", "P34": "· 🏢 带有数据中心机房标记", "P35": "🔍 其他旁证线索", "P36": "⚪ 还没去打听呢", "P37": "🌍 地区：{…}", "P38": "🏢 接入机房：{…}", "P39": "👀 看看赛博大善人 Cloudflare 觉得你是从哪个国家、哪座机房钻出来的 🕵️‍♂️", "P40": "💡 Cloudflare 可是全世界最会认「你从哪儿来」的行家之一；连上的机房离你越近，上网冲浪通常就越快越丝滑哦 🏄‍♂️✨！", "P41": "📭 没收到回执呢（{…}）", "P42": "📡 STUN 是浏览器里的 WebRTC 用来打听「我真实的公网地址是多少」的悄悄话协议；咱们用一模一样的方法去试探一次 🕵️‍♂️✨！", "P43": "💡 啥叫「DNS 泄漏」呢？就是你明明以为流量都穿好代理隐身衣了 🧥，结果查域名的活儿还是交给了本地运营商，一下子就暴露行踪啦 🙈！", "P44": "⚠️ 另外还发现了可疑的 DNS 劫持迹象哦（明明根本不存在的乱码域名，居然也被强行塞了个 IP 地址回来 👻）！", "P45": "✅ 太棒啦！系统 DNS 和公共 DNS 的出口完全一致（{…}）🎉", "P46": "🤔 系统 DNS 出口在 {…}，但公共 DNS 出口却在 {…}：俩人分道扬镳，说明你的域名解析走了两套不同的路线哦 🛤️！", "P47": "📍 系统 DNS 出口在 {…}；但公共 DNS 联系不上（可能是被拦住了 🚧，或者被代理软件全权接管啦 🦸‍♂️）。", "P48": "📭 系统 DNS 没回信；不过公共 DNS 的出口在 {…} ✨。", "P49": "😱 两种 DNS 都没拿到回执，可能整条 DNS 查询通道都被拦截或接管啦 🚧！", "P50": "🟢 畅通可用", "P51": "🔴 连不上呢", "P52": "🟡 会跳出人机验证考你 🧩", "P53": "🟠 网站返回了奇奇怪怪的意外内容 👽", "P54": "🏠 出口就是咱们本机的地址：说明这股流量乖乖走了直连，没进代理隧道哦 🍃！", "P55": "✈️ 出口国家/地区在 {…}：流量已经坐上代理小飞机，经过异地节点出去啦 🌍✨！", "P56": "🔀 出口地址和咱们本机不一样哦", "P57": "🛡️ 没拿到 STUN 回执：说明 UDP 流量可能被严严实实挡住了（不过别慌，这种情况下 WebRTC 反而绝对不会泄漏真实 IP 哦 ✌️✨）！", "P58": "🚨 哎呀！STUN 一眼就看到了咱们本机的真实地址 {…}：这意味着浏览器的 WebRTC 可能会把你的真实 IP 暴露给网站哦 🙈！", "P59": "👀 STUN 看到的地址是 {…}：这就是浏览器通过 WebRTC 会向外界展示的面孔 🎭。", "P60": "⚪ 还没开始检测呢 🐣", "P61": "😭 全军覆没连不上：你去逛境外网站时，那些人机验证的勾选框很可能会转圈圈加载不出来哦 🧩💦。", "P62": "😅 有 {…} 个站点一上来就甩给你人机验证页：看来你现在用的这条出口线路被风控系统「重点关照」啦 🚨！", "P63": "🎉 全都能丝滑加载！看来你现在的 IP 表现很乖，暂时没有被风控针对哦 ✌️✨！", "P64": "📊 {…}/{…} 个可用，还有 {…} 个暂时连不上 🤔", "P65": "🔌 网口代号（比如 en0 / en7）", "P66": "🏷️ 这是系统给每块网卡起的内部小名。外接的 USB 网卡只要换个插口，名字就可能变掉 🎭；所以咱们认网卡只认它永恒不变的 MAC 地址，不看这个小名哦 🎯！", "P67": "🪪 MAC 地址（物理地址）", "P68": "🏭 网卡出厂时就烙在芯片上的唯一身份证号。学校就是靠 MAC 来认你这台设备的——如果你换了新网卡或者换了别人的拓展坞 🔄，一定要去学校自助平台重新登记新 MAC，不然网关大哥绝对不放行哦 🚧！", "P69": "🏠 IPv4 地址", "P70": "🪧 这台电脑在吉大校园网里的专属门牌号。因为学校是按每个宿舍的墙上端口来分配固定地址的，所以必须老老实实照抄通知单 📝，不能用 DHCP 自动随便领一个哦 🙅‍♂️！", "P71": "🎭 子网掩码", "P72": "📏 用来划定门牌号里哪一段代表「咱们这栋宿舍楼」、哪一段代表「外面的世界」。要是填错了，电脑就会把同楼的网关当成外人，直接拒绝沟通连不上网啦 🙈！", "P73": "🚪 默认网关", "P74": "🦘 数据包走出咱们宿舍楼的第一跳（也就是楼道路由器）。它必须和你的 IP 在同一个网段里，不然你喊破喉咙发出去的包也没人接应哦 📣💦！", "P75": "📖 DNS（域名系统）：专门负责把好记的网址（比如 jlu.edu.cn）翻译成冷冰冰的 IP 数字 🔢。当它被代理软件接管劫持时，往往会把所有网址都先翻译成 198.18.x.x 这种临时假地址 🎭。", "P76": "🔗 链路本地地址（169.254.x.x）", "P77": "⛺ 当网卡还没领到正式 IP 地址时，自己给自己随便编的一个临时帐篷地址。Dr.Com 的登录认证包里规矩多，也得顺手带上它，没有的话就填 0 交差 ✨。", "P78": "🧭 路由 / 流量出口", "P79": "🚪 决定数据包到底从哪块网卡迈出家门。如果去往学校认证服务器（10.100.61.3）的出口变成了 utun 开头的虚拟网卡 🕳️，那就说明认证流量被代理软件半路截胡啦，大概率到不了学校网关哦 🚨！", "P80": "🚇 utun（虚拟隧道网卡）：这是 Clash、Surge、小火箭、WireGuard 等代理软件变出来的虚拟网卡 🪄。一旦它抢走了默认路由方向盘，所有流量都会先钻进代理隧道；所以咱们才需要在代理规则里把校园网段（10.0.0.0/8）设为直连（DIRECT）放行呀 🛣️✨！", "P81": "📡 无线 / 🔌 有线", "P82": "🛤️ 决定认证包走哪条物理通道。插网线（有线）和连 JLU.PC 共用同一套固定地址与账号密码 💳；而 JLU.WIFI 则是轻松愉快的动态网页认证，单算一套 🌐✨。", "P83": "🚀 测速单位（Mbps）", "P84": "🤓 科普小课堂：小写的 b（比特）和大写的 B（字节）差了整整 8 倍哦（1 字节 = 8 比特）！平时运营商宣传的「百兆宽带」指的是 100 Mbps，换算成咱们下载软件里看到的实际速度 MB/s，记得要除以 8 才是真实水平哈 🧮✨！", "P85": "🏓 Ping 延迟（ms 毫秒）", "P86": "⏱️ 数据包跑一个来回要花多少毫秒。在咱们校园网内部溜达一般不到 10ms，快如闪电 ⚡；如果绕道去了代理或异地 VPN 就会明显变慢 🐢，要是出现丢包就说明这条路有点颠簸不稳啦 🎢。", "P87": "😭 {…}：全部超时失联啦（丢包率 {…}% 💔）", "P88": "📊 %@：平均 %.0f ms（最快 %.0f / 最慢 %.0f，丢包 %.0f%% ✨）", "P89": "🏡 住宅 / 运营商原生 IP", "P90": "🏢 机房 IP（公有云 / 数据中心）", "P91": "📱 移动蜂窝网络 IP", "P92": "❓ 类型神秘未知", "P93": "· 🚨 已被标记为代理", "P94": "🏢 机房 IP 警告：去访问 Claude、网银或者流媒体网站时，被吃闭门羹拒绝的概率会高很多哦 😭💦", "P95": "🚨 已经有公开的反欺诈数据库把这个 IP 记在小本本上，标成代理或 VPN 出口啦 📝", "P96": "🤔 咦，IP 户口本上的归属国({…}) 和 Cloudflare 测出来的机房所在国({…}) 对不上号呢，这多半是个广播 IP 或者中转线路哦 📡！", "P97": "🇨🇳 出口还在中国大陆境内哦：那些傲娇的境外网站可能会直接按地区把你拒之门外 🚧", "P98": "🇨🇳 中国", "P99": "🇨🇳 中国大陆", "R01": "🌙 还有 {…} 分钟宿舍就要断电咯（周日到周四 23:30 准时熄灯）。文件先存好 💾，手机插上充电 🔌，刷完牙就钻进被窝吧 😴💤", "R02": "😴 只剩 {…} 分钟就要断电啦！赶紧保存、关灯、躺平——晚安，做个好梦 🌙✨", "R03": "🎉 周五、周六晚上不断电，可以多玩一会儿～不过也别熬太狠呀，手机记得充电 🔌🌙", "R04": "🌙 已经熄灯啦，屏幕的光会晃到室友的眼睛 👀 早点休息，明天还要早起呢 😴💤", "R05": "☀️ 早八时间到！起床洗漱、路上买个热乎的早餐 🥐，今天也要元气满满地出门呀 🏃‍♂️✨", "R06": "🛌 今天早上没有早八课～放心睡个美美的回笼觉吧，不过早餐还是要吃的哦 🥐😴✨", "R07": "🔔 放学啦！今天的课辛苦啦～去食堂吃顿热乎的 🍜，或者回宿舍躺一小会儿 🛌，晚上还有力气再战 ✨", "R08": "🧰 网络诊断", "R09": "🪪 校园卡（实体卡）", "R10": "开学报到时统一发，不用自己买。澡堂刷热水、图书馆门禁都用它。丢了要自己去线下缴费补办哦 💸", "R11": "📱 电话卡（别和校园卡搞混）", "R12": "开学初会有运营商来推销「校园卡」，其实和学校那张实体卡一点关系都没有，只是推销话术。按自己的流量需求决定办不办，流量够用就完全不用办，不强制。", "R13": "🌐 校园网（收费，但不是必须）", "R14": "20 元/月，一般按学期交 100 元。办了可以连各校区的无线，宿舍的有线也能用。不强制，但有些校内网站只有在校园网里才打得开。", "R15": "🎒 新生小贴士", "R16": "🔁 开机自启还没打开，重启后要自己再开一次 App", "R17": "去设置里打开", "R18": "开机自启", "R19": "照着下面的步骤走一遍（macOS 26 和 14/15 的叫法略有不同）：", "R20": "✅ 已开启：重启后会自动出现", "R21": "⚠️ 还没开启：重启后不会自己启动", "R22": "⏳ 已登记，但需要你在「系统设置 → 登录项与扩展」里点一下允许", "R23": "📦 你用的是 SD 卡/下载目录里的便携副本，不能开机自启；把它拖进「应用程序」再打开，然后回来开这个开关", "R24": "打开系统设置 → 登录项", "R25": "现在打开", "R26": "1️⃣ 点左上角苹果菜单  → 「系统设置」\n2️⃣ 左侧点「通用」\n3️⃣ 右侧点「登录项与扩展」（macOS 14/15 里叫「登录项」）\n4️⃣ 在「登录时打开」那一栏找到「JLU Gate」，把右边的开关打开\n5️⃣ 列表里没有它？点这一栏下面的「＋」，在弹出窗口选「应用程序」→ 找到「JLU Gate」→「打开」\n6️⃣ 如果提示「需要批准」，点「允许」，再输一次密码或按指纹\n7️⃣ 回到这里看到「✅ 已开启」就成功了\n⚠️ 前提：App 必须在「应用程序」文件夹里；放在 SD 卡或下载目录里，系统不会把它加进登录项", "R27": "📶 你被新设备挤下线了（JLU.WIFI 同时最多 3 台）。我正在后台悄悄帮你重新登录，不用管它～", "R28": "✅ 已经悄悄帮你登录好了，现在可以上网啦 🎉", "R29": "🔐 正在后台静默登录（不弹网页），请稍等…", "S01": "🌱 萌新指南 / 第一次用看这里", "S02": "👤 账号", "S03": "📧 学校邮箱前缀（比如 zhangcyy2122 或 zhangshanwu ✨）", "S04": "🔐 密码（安全锁在 Keychain 里 🛡️）", "S05": "留空不填 = 继续用之前存好的密码（{…}）💖", "S06": "🛤️ 链路设置", "S07": "🚪 接入方式", "S08": "🤖 自动判断", "S09": "🔌 有线网络", "S10": "👀 认准 Wi-Fi 名字，必须一模一样：JLU.PC / JLU.WIFI（大写字母、中间带个点 🟢）；", "S11": "⚠️ 遇到同名网络先留个心眼确认是不是学校的，可疑网络里千万别输账号哦 🛡️！", "S12": "🚀 通道底层实现", "S13": "🦅 BSD（默认首选，最贴近官方客户端的原汁原味 ✨）", "S14": "🍎 NW（苹果系统的网络框架）", "S15": "🤓 BSD：用原始 socket，能超精准地锁死源端口 61440 和指定网卡（IP_BOUND_IF）🎯；", "S16": "🍎 NW：走系统的 Network.framework，听系统路径管理的话。其实俩人发的是一样的 UDP 包 📦，", "S17": "平时默认用 BSD 就好 👍，哪天遇到系统傲娇限制了再换 NW 试试 🔄！", "S18": "📌 固定网络参数（只在有线 / JLU.PC 下派上用场 🛠️）", "S19": "🎉 你现在选的是 JLU.WIFI：地址动态分配 + 网页认证，下面这些复杂的静态参数统统不用管啦 🏖️！", "S20": "📝 学校分给你的专属固定地址，照着通知单抄就行（别抄成 DHCP 自动分的哦 🙅‍♂️）", "S21": "🎭 子网掩码", "S22": "一般填 255.255.255.0 准没错 ✨", "S23": "🚪 网关", "S24": "同网段的第一跳 🦘，通常是 x.x.x.254", "S25": "🏫 校内推荐用 10.10.10.10；到了校外可以换成 223.5.5.5 🌐✨", "S26": "🪪 登记 MAC", "S27": "在学校登记的那块网卡的真实物理地址（别填成系统随机生成的假 MAC 哦 🕵️‍♂️）", "S28": "🐢 兼容模式：关掉酷炫的液态玻璃特效（在虚拟机或老显卡上跑得更稳当，重启 App 生效哦 🔄✨）", "S29": "🎭 当系统开了私有/随机 MAC 时，强行用登记的 MAC 去发认证包（高阶魔法 🪄）", "S30": "这招只改认证信件里的 MAC 签名 ✉️，不动网卡本身。不过最稳妥的办法还是去系统设置里把「私有无线局域网地址」关掉啦 👍✨！", "S31": "📋 静态网络参数", "S32": "👀 系统当前读数（仅供参考核对哦）", "S33": "🧭 路由：{…}", "S34": "🎴 网卡选择", "S35": "👉 派哪块网卡出战？", "S36": "🤖 自动挑选（按 MAC 认领 ✨）", "S37": "🎯 按登记的 MAC 自动帮你选一次", "S38": "📡 链路探测", "S39": "🚀 打开 App 时自动连接（记住账号密码后就安安静静帮你连，绝不打扰 🤫💖）", "S40": "🕵️‍♂️ 自动探测（悄悄发 1 个 challenge 包看看是不是在校园网里 ✨）", "S41": "关掉之后就只做普通的 204 探针检测，绝不主动给校园网关发任何认证包 🤐🛡️。", "S42": "🌐 网页认证入口 URL（留空就会自动帮你找哦 🔍）", "S43": "🛡️ 路由保障", "S44": "📍 当前状态：{…}", "S45": "🦸‍♂️ 允许后台小助手添加 -ifscope 直连路由（需要管理员点个头授权哦 🔑）", "S46": "🚧 后台 helper 属于 M2.5 阶段的酷炫功能，这个版本还没带上它；没授权时咱们会贴心地给你一条可以复制的命令 📋✨。", "S47": "🌟 版本更新", "S48": "🔍 检查更新", "S49": "🏷️ 当前版本 {…}", "S50": "🧪 高级玩家区", "S51": "🖥️ 服务器地址", "S52": "🔌 服务器端口", "S53": "🔒 本地端口（必须锁死 61440 哦）", "S54": "🌅 开机自动启动", "S55": "💾 保存设置", "S56": "✅ 存好啦！", "S57": "✖️ 关闭", "S58": "📥 读取系统当前值", "S59": "🔄 重新检测一下", "S60": "📋 导入参数卡", "S61": "🧹 清空网络参数", "S62": "🗑️ 忘掉已保存的密码", "S63": "💥 重置本机所有配置…", "S64": "⏳ 正在努力检查中…", "S65": "🎉 已经是最新版啦！", "S66": "🎁 发现新版本 {…}！", "S67": "🚀 下载并立刻安装", "S68": "📥 先只下载不安装", "S69": "🟢 A 层 · 出口正好就是 {…}，不用任何特权就能丝滑使用 ✨！", "S70": "🔵 B 层 · 由贴心的 helper 给 {…} 加上 /32 专属路由 🛣️", "S71": "🟡 C 层 · 需要你搭把手，手动给 {…} 加一条路由命令 ✍️", "S72": "🔴 拿不到路由信息呢（可能是网卡还在睡懒觉，或者没找到去服务器的路 🗺️💤）", "S73": "⚪ 还没检测过呢 🐣", "T01": "🌟 吉大人生存必备常用站点", "T02": "🔍 搜搜站点名字、域名或者你想干嘛…", "T03": "💡 标着「仅校内」的站点在外面是打不开的哦，得先连上 WebVPN 🌉；标着「需 VPN」意思是网页能打开，但里面的核心资源（比如知网论文 📚）需要校园网环境才能看 ✨。", "T04": "🙈 翻遍了也没找到匹配的站点呢，换个词试试？", "T05": "📰 校园网门户 / 今日份校园小广告", "T06": "🌐 打开门户看看", "T07": "每次认证完，学校经常会热情地弹一个欢迎/通知页 🎉；咱们这儿不烦人地自动弹窗，直接把地址留给你，想看的时候随时点开用浏览器看 👀✨！", "T08": "🏛️ 我的专属学院", "T09": "🚀 打开学院官网", "T10": "🔄 换个学院", "T11": "✍️ 填一下学号，或者手动选一次学院，以后小助手就能一眼认出你的学院啦（放心，只乖乖存在你自己的电脑里 🔒✨）", "T12": "🎓 你的学号", "T13": "🔍 搜搜学院名字或域名…", "T14": "📂 展开全部 {…} 个学院大家庭", "T15": "🏫 咱们吉大一共有 {…} 个学院呢 ✨", "T16": "🎯 找到了 {…} 个匹配的学院，先给你展示前 6 个；继续打字可以缩小范围，或者直接点下面全部展开哦 👇✨", "T17": "🎯 匹配到 {…} 个结果", "T18": "🚀 打开", "T19":